const test = require('node:test');
const assert = require('node:assert/strict');
const { logLine } = require('../support/service.cjs');
const { redact } = require('../support/redact.cjs');
function freezeTree(value) {
  if (value && typeof value === 'object') {
    Object.values(value).forEach(freezeTree); Object.freeze(value);
  }
  return value;
}
test('redact every object depth including objects inside arrays', () => {
  const record = freezeTree({
    token:'top-secret', session:{token:'t-28',name:'Lin',details:{pin:1234}},
    events:[{pin:'0042'},[null,{token:{raw:'never log'}}],0,false,''],
    Token:'public-case',label:'token remains ordinary text'
  });
  const expected = {
    token:'[hidden]',session:{token:'[hidden]',name:'Lin',details:{pin:'[hidden]'}},
    events:[{pin:'[hidden]'},[null,{token:'[hidden]'}],0,false,''],
    Token:'public-case',label:'token remains ordinary text'
  };
  const output = logLine(record);
  assert.equal(output.endsWith('\n'),true);
  assert.deepEqual(JSON.parse(output),expected);
  assert.equal(record.session.token,'t-28');
  const copy = redact(record);
  assert.notStrictEqual(copy,record);
  assert.notStrictEqual(copy.session,record.session);
  assert.notStrictEqual(copy.events,record.events);
  assert.notStrictEqual(copy.events[1],record.events[1]);
  const plain = {a:[{b:1}],empty:{}}; const clean = redact(plain);
  clean.a[0].b=9; clean.empty.changed=true;
  assert.deepEqual(plain,{a:[{b:1}],empty:{}});
  for (const value of [null,0,false,'']) assert.equal(redact(value),value);
  assert.deepEqual(redact([]),[]); assert.deepEqual(redact({}),{});
  assert.deepEqual(redact({pin:null,token:false}),{pin:'[hidden]',token:'[hidden]'});
});

